    @log_input_and_output
    def _get_sw_version(self):
        """
        Gets SW version from blackbox file.

        :return: SW version, e.g. :
        {'Item type': 'SW_version',
         'Last write': '2020-09-20T10:45:08+00:00',
         'Last write ISTI': '1812212.319000',
         'File [0] name': 'rfsw-package-srm7_0x8C16656E.tar',
         'File [0] version': '0x8C16656E',
         'File [0] status': 'Active',
         'File [1] name': 'rfsw-package-srm7_0x31DB62E1.tar',
         'File [1] version': '0x31DB62E1',
         'File [1] status': 'Passive'}
        :rtype: dict
        :raises BlackboxSwVersionError when SW version not found in blackbox file
        """
        for sw_ind, line in enumerate(self._bbox_lines):
            if 'Item type: SW_version' in line and 'history' not in line:
                sw_version = {}
                for i in range(len(self._mandatory_sw_version_items)):
                    sw_version.update(
                        self._get_key_value_pair_from_blackbox_line(sw_ind + i))
                return sw_version
        raise BlackboxSwVersionError('SW version not found in blackbox file: {}.'.format(self._path))

    @log_input_and_output
    def _get_bts_alarm_history(self):
        """
        Gets BTS alarm history from blackbox file.
        Every alarm info contains: BTSAlarmId, BTSAlarmSource, BTSAlarmSeverity, 1 - start|0- cancel,
        date ISO8601 second, internalFaultId, isSentToMa
        :return: BTS alarm history, e.g. :
        [{'BTSAlarmId': '1931', 'BTSAlarmSource': 'module', 'BTSAlarmSeverity': 'critical', 'activity_state': '1',
          'date': datetime(2024, 8, 28, 10, 35, 57), 'last_write_isti':1948487.519000, 'internalFaultId': '1162',
          'isSentToMa': '1'},
         {'BTSAlarmId': '1931', 'BTSAlarmSource': 'module', 'BTSAlarmSeverity': 'critical', 'activity_state': '0',
          'date': datetime(2024, 8, 28, 10, 40, 56), 'internalFaultId': '1162',
          'isSentToMa': '1'},
         {'BTSAlarmId': '1926', 'BTSAlarmSource': 'module', 'BTSAlarmSeverity': 'critical', 'activity_state': '1',
          'date': datetime(2024, 9, 2, 16, 2, 7), 'internalFaultId': '1334',
          'isSentToMa': '1'}]
        :rtype: list of dict
        :raises BlackboxBtsAlarmHistoryError when BTS alarm history not found in blackbox file
        """
        bts_alarm_history = []
        bts_alarm_part = False
        alarm_keys = ['BTSAlarmId', 'BTSAlarmSource', 'BTSAlarmSeverity', 'activity_state', 'date', 'last_write_isti',
                      'internalFaultId', 'isSentToMa']
        for line in self._bbox_lines:
            if 'Item type: BtsAlarmHistory' in line:
                bts_alarm_part = True
                continue
            if bts_alarm_part:
                if '---' in line:
                    break
                if line:
                    alarm_info_items = line.split(',')
                    alarm_info = {}
                    for ind, alarm_info_item in enumerate(alarm_info_items):
                        if alarm_keys[ind] == 'date':
                            date = alarm_info_item.replace('T', ' ').replace('Z', '').strip('<>')
                            try:
                                alarm_info[alarm_keys[ind]] = datetime.strptime(date, '%Y-%m-%d %H:%M:%S.%f')
                            except ValueError:
                                alarm_info[alarm_keys[ind]] = datetime.strptime(date, '%Y-%m-%d %H:%M:%S')
                            continue
                        alarm_info[alarm_keys[ind]] = alarm_info_item
                    bts_alarm_history.append(alarm_info)
        if not bts_alarm_part:
            raise BlackboxBtsAlarmHistoryError('BTS alarm history not found in blackbox file: {}.'.format(self._path))
        return bts_alarm_history

    @log_input_and_output
    def _check_if_all_mandatory_items_in_received_structure(self, mandatory_items, received_items, items_type):
        """
        Checks if all mandatory keys are in received structure.

        :param mandatory_items: list of mandatory items
        :type mandatory_items: list
        :param received_items: list of received items
        :type received_items: list
        :param items_type: type of items, e.g. 'SW version'
        :type items_type: str
        :raises BlackboxStructureError when mandatory items are missing in received items
        """
        if not all(mandatory_item in received_items
                   for mandatory_item in mandatory_items):
            raise BlackboxStructureError('Blackbox structure is not correct. Mandatory items are missing for {}. '
                                         'Expected items: {}'
                                         'Received items: {}'.format(items_type, mandatory_items, received_items))

    def _get_key_value_pair_from_blackbox_line(self, index):
        return {self._bbox_lines[index].split(':', 1)[0]: self._bbox_lines[index].split(':', 1)[-1].strip()}

    def _get_key_list_value_pair_from_blackbox_line(self, index):
        return {self._bbox_lines[index].split(':', 1)[0]: self._bbox_lines[index].split(':', 1)[-1].strip().split()}

    @staticmethod
    @log_input_and_output
    def _get_sw_version_and_name_for_specific_status(sw_data, status='active'):
        """
        Gets SW version and name for specific status.

        :param sw_data: dictionary with software data from blackbox or SWmanShellCommand -i command, e.g. :
        {'Item type': 'SW_version',
        'Last write': '2020-09-20T10:45:08+00:00',
        'File [0] name': 'rfsw-package-srm7_0x8C16656E.tar',
        'File [0] version': '0x8C16656E',
        'File [0] status': 'Active',
        'File [1] name': 'rfsw-package-srm7_0x31DB62E1.tar',
        'File [1] version': '0x31DB62E1',
        'File [1] status': 'Passive'}
        :type sw_data: dict
        :param status: status for which SW version and name will be returned - 'active' or 'passive'
        :type status: str
        :return: SW name and version, e.g. :
        ('rfsw-package-srm7_0x05D3A366.tar', '0x05D3A366')
        :rtype: tuple
        """
        if 'File [0] status' in sw_data:
            sw_file_ind = 0 if status in sw_data['File [0] status'].lower() else 1
        else:
            sw_file_ind = 0 if status in sw_data['File [0] usage'].lower() else 1
        return sw_data['File [{}] name'.format(sw_file_ind)], sw_data['File [{}] version'.format(sw_file_ind)]

    @log_input_and_output
    def _get_specific_alarm_occurrences_in_bbox(self, expected_fault_id):
        """
        Gets specific alarm occurrences from blackbox file.

        :param expected_fault_id: expected fault id
        :type expected_fault_id: str
        :return: alarm occurrences, e.g. :
        [{'BTSAlarmId': '1926', 'BTSAlarmSource': 'module', 'BTSAlarmSeverity': 'critical', 'activity_state': '1',
          'date': datetime(2024, 9, 2, 16, 2, 7), 'internalFaultId': '1334',
          'isSentToMa': '1'}]
        :rtype: list of dict
        """
        return [alarm_info for alarm_info in self._get_bts_alarm_history() if
                alarm_info['BTSAlarmId'] == str(expected_fault_id)]
